              title: 'Preamble Of Indian Constitution (ભારતીય બંધારણનું આમુખ) - સંપૂર્ણ વિશ્લેષણ',
              channelName: 'Utkarsh Classes (By Dr. Dinesh Gehlot)',
              duration: '27:18 Min',
              summary: 'આ લેક્ચરમાં ડૉ. દિનેશ ગેહલોત દ્વારા બંધારણના આમુખ (પ્રસ્તાવના) ની સંપૂર્ણ સમજૂતી આપવામાં આવી છે. જેમાં આમુખનો ઐતિહાસિક સ્ત્રોત (અમેરિકા અને નેહરુજીનો ઉદ્દેશ પ્રસ્તાવ), સત્તાનો સ્ત્રોત ("અમે ભારતના લોકો"), રાજ્યના સ્વરૂપના ૫ શબ્દોનો સાચો ક્રમ (સાર્વભૌમ, સમાજવાદી, બિનસાંપ્રદાયિક, લોકશાહી, પ્રજાસત્તાક), ૩ પ્રકારનો ન્યાય, ૫ પ્રકારની સ્વતંત્રતા, ૨ પ્રકારની સમાનતા, ૪૨મો સુધારો ૧૯૭૬ (૩ નવા શબ્દો), બેરૂબારી કેસ વિ. કેશવાનંદ ભારતી કેસ (મૂળભૂત માળખું) અને મહત્વના કથનો (કુંડળી, ઓળખપત્ર, આત્મા) ની ઊંડાણપૂર્વક છણાવટ કરવામાં આવી છે.',
              keyTakeaways: [
                '[01:15] આમુખનો ખ્યાલ: વિશ્વમાં સૌપ્રથમ અમેરિકાના બંધારણમાં; ભાષા શૈલી ઓસ્ટ્રેલિયાના બંધારણમાંથી પ્રેરિત.',
                '[03:20] ઐતિહાસિક આધાર: પંડિત જવાહરલાલ નેહરુ દ્વારા ૧૩ ડિસેમ્બર ૧૯૪૬ ના રોજ રજૂ કરાયેલ "ઉદ્દેશ પ્રસ્તાવ" (૨૨ જાન્યુઆરી ૧૯૪૭ ના રોજ સ્વીકૃત).',
                '[05:40] સત્તાનો સ્ત્રોત: "અમે ભારતના લોકો" (We, the People of India) - બંધારણની અંતિમ સત્તા ભારતીય જનતામાં નિહિત છે (Popular Sovereignty).',
                '[08:15] ભારતીય રાજ્યનું સ્વરૂપ (૫ શબ્દોનો સાચો ક્રમ): ૧. સંપૂર્ણ પ્રભુત્વ-સંપન્ન/સાર્વભૌમ, ૨. સમાજવાદી, ૩. પંથનિરપેક્ષ/બિનસાંપ્રદાયિક, ૪. લોકશાહી, ૫. પ્રજાસત્તાક/ગણરાજ્ય.',
                '[11:30] "સાર્વભૌમ" (Sovereign): ભારત આંતરિક અને બાહ્ય નિર્ણયો લેવા માટે સંપૂર્ણ સ્વતંત્ર છે, કોઈપણ વિદેશી સત્તાને આધીન નથી.',
                '[13:10] "સમાજવાદી" (Socialist): લોકશાહી સમાજવાદ (Democratic Socialism); ગાંધીવાદ અને માર્ક્સવાદનો સુમેળ (ગાંધીવાદ તરફ વધુ ઝુકાવ).',
                '[15:20] "પંથનિરપેક્ષ" (Secular): રાજ્યનો કોઈ સત્તાવાર રાજ્યધર્મ નથી; રાજ્ય બધા ધર્મો પ્રત્યે સમાન આદર (સર્વધર્મ સમભાવ) રાખે છે.',
                '[17:05] "લોકશાહી" અને "પ્રજાસત્તાક": રાજ્યના વડા (રાષ્ટ્રપતિ) વંશપરંપરાગત નહીં પણ પ્રજા દ્વારા અપ્રત્યક્ષ ચૂંટાયેલા છે.',
                '[18:45] બંધારણના ઉદ્દેશો - ૩ પ્રકારનો ન્યાય: સામાજિક, આર્થિક અને રાજકીય ન્યાય (૧૯૧૭ની રશિયન ક્રાંતિમાંથી પ્રેરિત).',
                '[20:10] ૫ પ્રકારની સ્વતંત્રતા: વિચાર, અભિવ્યક્તિ, વિશ્વાસ, ધર્મ અને ઉપાસનાની સ્વતંત્રતા (૧૭૮૯ની ફ્રેન્ચ ક્રાંતિમાંથી).',
                '[21:30] ૨ પ્રકારની સમાનતા: પ્રતિષ્ઠા (દરજ્જો) અને તકની સમાનતા; વ્યક્તિનું ગૌરવ અને રાષ્ટ્રની એકતા-અખંડિતતા વધારતી બંધુતા.',
                '[22:50] ૪૨મો બંધારણીય સુધારો ૧૯૭૬: ૩ નવા શબ્દો ઉમેરાયા - સમાજવાદી, પંથનિરપેક્ષ (બિનસાંપ્રદાયિક) અને અખંડિતતા (માત્ર ૧ જ વાર સુધારો).',
                '[24:15] બેરૂબારી કેસ (૧૯૬૦): સુપ્રીમ કોર્ટે કહ્યું "આમુખ બંધારણનો ભાગ નથી", તેથી ૩૬૮ હેઠળ સુધારો ન થઈ શકે.',
                '[25:30] કેશવાનંદ ભારતી કેસ (૧૯૭૩): ૧૩ જજોની બેંચે ઠરાવ્યું કે "આમુખ બંધારણનો અભિન્ન ભાગ છે" અને ૩૬૮ હેઠળ મૂળભૂત માળખું જાળવી સુધારી શકાય.',
                '[26:45] કથનો: કે.એમ. મુનશી ("રાજકીય કુંડળી"), એન.એ. પાલખીવાલા ("ઓળખપત્ર"), ઠાકુરદાસ ભાર્ગવ ("બંધારણનો આત્મા & આભૂષણ"), અર્નેસ્ટ બાર્કર ("કી નોટ").',
