                '[30:40] એસ. કે. ધાર આયોગ (૧૯૪૮) & JVP સમિતિ (૧૯૪૮): ભાષાવાર રાજ્યોની રચના ફગાવી, વહીવટી સરળતાને પ્રાથમિકતા આપી.',
