  4. **સૈયદ મોહમ્મદ સાદુલ્લા** (Syed Mohammad Saadulla - મુસ્લિમ લીગ)
  5. **એન. માધવરાવ** (N. Madhava Rau) -> *બી. એલ. મિત્તર (B.L. Mitter) ની નાદુરસ્ત તબિયતના કારણે રાજીનામું આપતાં તેમના સ્થાને આવ્યા.*
