### 💡 ૧૯૫૧ નો પ્રથમ બંધારણીય સુધારો - એક ઐતિહાસિક કોયડો
* **પ્રશ્ન:** ભારતીય બંધારણમાં પ્રથમ સામાન્ય ચૂંટણી ૧૯૫૧-૫૨ માં થઈ અને નવી ચૂંટાયેલી લોકસભા/રાજ્યસભાની પ્રથમ બેઠક **૧૩ મે ૧૯૫૨** ના રોજ મળી. તો પછી **૧મો બંધારણીય સુધારો ૧૯૫૧ માં કઈ સંસદે કર્યો?**
