### 📜 ૨૬ નવેમ્બર ૧૯૪૯ વિ. ૨૬ જાન્યુઆરી ૧૯૫૦ (કલમ ૩૯૪ નું રહસ્ય)
* **૨૬ નવેમ્બર ૧૯૪૯ (અંગીકાર / Adopted):**
  * બંધારણ સભા દ્વારા બંધારણ પસાર અને સ્વીકાર કરવામાં આવ્યું.
  * **અનુચ્છેદ ૩૯૪ મુજબ ૧૬ અનુચ્છેદો તાત્કાલિક લાગુ થયા:**
    * **૫, ૬, ૭, ૮, ૯** (નાગરિકતા - Citizenship)
    * **૬૦** (રાષ્ટ્રપતિના શપથ)
    * **૩૨૪** (ચૂંટણી પંચ - Election Commission)
    * **૩૬૬, ૩૬૭** (વ્યાખ્યાઓ અને અર્થઘટન)
    * **૩૭૯, ૩૮૦, ૩૮૮, ૩૯૧, ૩૯૨** (કામચલાઉ સંસદ અને સંક્રમણકાલીન જોગવાઈઓ)
    * **૩૯૩** (સંક્ષિપ્ત નામ - 'ભારતનું બંધારણ')
    * **૩૯૪** (આ અનુચ્છેદ પોતે - અમલીકરણ તારીખ).
  * વર્ષ ૨૦૧૫ થી દર વર્ષે ૨૬ નવેમ્બરને **"બંધારણ દિવસ" (Constitution Day)** તરીકે ઉજવાય છે.
* **૨૬ જાન્યુઆરી ૧૯૫૦ (સંપૂર્ણ અમલ):**
  * ૧૯૩૦ ના ૨૬મી જાન્યુઆરીના **"પૂર્ણ સ્વરાજ દિવસ"** (૧૯૨૯ લાહોર અધિવેશન) ના ઐતિહાસિક દિવસની સ્મૃતિરૂપે સંપૂર્ણ બંધારણ આ દિવસે લાગુ થયું.
  * **અનુચ્છેદ ૩૯૫:** આ અનુચ્છેદ દ્વારા બ્રિટિશ શાસનના *ભારત શાસન અધિનિયમ ૧૯૩૫* અને *ભારતીય સ્વતંત્રતા અધિનિયમ ૧૯૪૭* ને રદ (Repeal) કરવામાં આવ્યા.

