  2. *"બંધારણ સભા માત્ર હિન્દુઓની સંસ્થા છે."*
* **લોર્ડ સાયમન:** બંધારણ સભાને *"હિન્દુઓની સભા"* ગણાવી.
* **ગ્રેનવિલ ઓસ્ટિન (Granville Austin):**
