            'અનુચ્છેદ ૩૨: સંવિધાનિક ઉપચારોનો અધિકાર - ડૉ. બાબાસાહેબ આંબેડકર દ્વારા "બંધારણનો આત્મા અને હૃદય", સર્વોચ્ચ અદાલતની ૫ રિટ્સ (બંદી પ્રત્યક્ષીકરણ, પરમાદેશ, પ્રતિષેધ, ઉત્પ્રેષણ, અધિકાર પૃચ્છા)',
