            'અનુચ્છેદ ૩૩, ૩૪, ૩૫: સશસ્ત્ર દળોના મૂળભૂત હકો પર સંસદીય પ્રતિબંધ (૩૩), માર્શલ લો / લશ્કરી શાસનમાં સંસદીય ક્ષતિપૂર્તિ (૩૪), મૂળભૂત અધિકારો લાગુ કરવા માત્ર સંસદની કાયદાકીય સત્તા (૩૫)',
            'ભાગ-૪: રાજ્યનીતિના માર્ગદર્શક સિદ્ધાંતો - DPSP (અનુચ્છેદ ૩૬ થી ૫૧): આયર્લેન્ડ સ્ત્રોત, ૧૯૩૫ ના ઇન્સ્ટ્રુમેન્ટ ઓફ ઇન્સ્ટ્રક્શન્સ સમાન, કલ્યાણકારી રાજ્ય (Welfare State) અને સામાજિક-આર્થિક લોકશાહી',
            'અનુચ્છેદ ૩૬ & ૩૭: રાજ્યની વ્યાખ્યા (કલમ ૧૨ મુજબ), અદાલત દ્વારા અપ્રવર્તનીય (Non-justiciable) છતાં દેશના શાસનમાં પાયારૂપ (Fundamental in Governance) અને રાજ્યની ફરજ',
            'અનુચ્છેદ ૩૮ & ૩૯: સામાજિક-આર્થિક ન્યાય, અસમાનતા ઘટાડવી (૩૮-૨ ૪૪મો સુધારો), આજીવિકા સાધનો, સંપત્તિ વહેંચણી (૩૯-b/c), સ્ત્રી-પુરુષ સમાન કામ માટે સમાન વેતન (૩૯-d)',
            'અનુચ્છેદ ૩૯-A, ૪૦, ૪૧, ૪૨, ૪૩, ૪૩-A, ૪૩-B: મફત કાનૂની સહાય (NALSA), ગ્રામ પંચાયતો (૭૩મો સુધારો), કામ-શિક્ષણ-લોકસહાય (મનરેગા), પ્રસૂતિ સહાય, નિર્વાહ વેતન & કુટિર ઉદ્યોગ, કામદારોની ભાગીદારી, સહકારી મંડળીઓ (૯૭મો સુધારો)',
            'અનુચ્છેદ ૪૪, ૪૫, ૪૬, ૪૭, ૪૮, ૪૮-A, ૪૯, ૫૦, ૫૧: સમાન નાગરિક સંહિતા (UCC), ૬ વર્ષથી નાના બાળકોની સંભાળ (૮૬મો સુધારો), SC/ST ઉત્થાન, નશાબંધી, ગૌહત્યા પ્રતિબંધ, પર્યાવરણ-વન્યજીવ રક્ષણ (૪૨મો સુધારો), સ્મારક સંરક્ષણ, કારોબારીથી ન્યાયતંત્ર અલગતા, આંતરરાષ્ટ્રીય શાંતિ & વિદેશ નીતિ',
            'DPSP નું ત્રિસ્તરીય વર્ગીકરણ (સમાજવાદી, ગાંધીવાદી, ઉદારવાદી-બૌદ્ધિક) અને ભાગ-૪ બહારના નિર્દેશો (અનુચ્છેદ ૩૩૫, ૩૫૦-A, ૩૫૧)',
            'ભાગ-૪-A: મૂળભૂત ફરજો (અનુચ્છેદ ૫૧-A) - USSR સ્ત્રોત, જાપાન સિવાય લોકશાહી દેશોમાં વિરલ, સરદાર સ્વર્ણસિંહ સમિતિ (૧૯૭૬ - ૮ ફરજો ભલામણ, કર ભરવા & સજાની અસ્વીકૃત ભલામણો)',
            '૪૨મો સુધારો ૧૯૭૬ (૧૦ ફરજો, અમલ: ૩ જાન્યુઆરી ૧૯૭૭ - મૂળભૂત ફરજ દિન), ૮૬મો સુધારો ૨૦૦૨ (૧૧મી ફરજ - ૫૧-A(k) ૬ થી ૧૪ વર્ષ બાળ શિક્ષણ વાલી ફરજ)',
            'તમામ ૧૧ મૂળભૂત ફરજો (૫૧-A (a) થી (k)): બંધારણ-રાષ્ટ્રધ્વજ-રાષ્ટ્રગાન આદર, રાષ્ટ્રીય આંદોલનના આદર્શો, સાર્વભૌમત્વ-એકતા-અખંડિતતા, દેશ રક્ષણ, ભ્રાતૃત્વ & સ્ત્રી સન્માન, સામાસિક સંસ્કૃતિ, પર્યાવરણ-વન્યજીવ (g), વૈજ્ઞાનિક અભિગમ (h), જાહેર મિલકત (i), ઉત્કૃષ્ટતા (j), બાળ શિક્ષણ (k)',
            'કાનૂની સ્વરૂપ & વર્મા સમિતિ (૧૯૯૯): અપ્રવર્તનીય (Non-justiciable) છતાં સંસદીય કાયદાઓ દ્વારા અમલ (રાષ્ટ્રગૌરવ અપમાન ૧૯૭૧, વન્યજીવ સંરક્ષણ ૧૯૭૨, જાહેર મિલકત ૧૯૮૪ વગેરે), માત્ર નાગરિકો માટે',
