              title: 'સમાનતાનો અધિકાર || Fundamental Rights (ભાગ-૩: અનુચ્છેદ ૧૨ થી ૧૮) - સંપૂર્ણ વિશ્લેષણ',
              channelName: 'Utkarsh Classes (By Dr. Dinesh Gehlot)',
              duration: '44:50 Min',
              summary: 'આ લેક્ચરમાં ડૉ. દિનેશ ગેહલોત દ્વારા બંધારણના ભાગ-૩ (મૂળભૂત અધિકારો) અને વિશેષ રૂપે "સમાનતાનો અધિકાર" (Right to Equality - અનુચ્છેદ ૧૪ થી ૧૮) નું ઊંડાણપૂર્વક વિશ્લેષણ કરવામાં આવ્યું છે. જેમાં મૂળભૂત હકોનો ઇતિહાસ (અમેરિકા સ્ત્રોત, ૭ માંથી ૬ હકો), અનુચ્છેદ ૧૨ (રાજ્યની વ્યાખ્યા), અનુચ્છેદ ૧૩ (ન્યાયિક સમીક્ષા), અનુચ્છેદ ૧૪ (કાયદા સમક્ષ સમાનતા વિ. કાયદાનું સમાન રક્ષણ), અનુચ્છેદ ૧૫ (ભેદભાવ નિષેધના ૫ આધારો અને અનામત અપવાદો), અનુચ્છેદ ૧૬ (જાહેર નોકરીમાં ૭ આધારો, મંડલ પંચ અને ઇન્દિરા સાહની કેસ), અનુચ્છેદ ૧૭ (અસ્પૃશ્યતા નિવારણ કાયદાઓ) અને અનુચ્છેદ ૧૮ (ખિતાબોની નાબૂદી અને પદ્મ એવોર્ડ્સ) નું પરીક્ષાલક્ષી માર્ગદર્શન આપવામાં આવ્યું છે.',
              keyTakeaways: [
                '[01:45] મૂળભૂત હકોનો સ્ત્રોત: યુ.એસ.એ. (USA) ના "Bill of Rights" માંથી; ભાગ-૩ ને "ભારતનો મેગ્ના કાર્ટા" કહેવાય છે.',
                '[03:30] હકોની સંખ્યા: મૂળ બંધારણમાં ૭ અધિકારો હતા; ૪૪મા સુધારા ૧૯૭૮ દ્વારા મિલકતનો અધિકાર (અનુચ્છેદ ૩૧) રદ કરી કલમ ૩૦૦-ક હેઠળ માત્ર કાનૂની હક બનાવાયો; હાલમાં ૬ હકો છે.',
                '[05:50] માત્ર ભારતીય નાગરિકોને મળતા ૫ હકો: અનુચ્છેદ ૧૫, ૧૬, ૧૯, ૨૯ અને ૩૦ (યાદ રાખવાની શોર્ટ ટ્રીક: ૧૫, ૧૬, ૧૯, ૨૯, ૩૦).',
                '[08:30] અનુચ્છેદ ૧૨ - "રાજ્ય" (State) ની વ્યાખ્યા: કેન્દ્ર/રાજ્ય સરકાર, સંસદ, વિધાનમંડળ, તમામ સ્થાનિક સત્તાવાળાઓ (પંચાયતો, પાલિકાઓ) અને વૈધાનિક સંસ્થાઓ (LIC, ONGC, SAIL વગેરે).',
                '[12:15] અનુચ્છેદ ૧૩ - ન્યાયિક પુનરાવલોકન (Judicial Review): મૂળભૂત હકોનું ઉલ્લંઘન કરતો કોઈપણ કાયદો તે હદે શૂન્ય (Void) બનશે; ગ્રહણનો સિદ્ધાંત અને પૃથક્કરણીયતાનો સિદ્ધાંત.',
                '[15:40] અનુચ્છેદ ૧૪ - બે સંકલ્પનાઓ: ૧. "કાયદા સમક્ષ સમાનતા" (બ્રિટિશ સ્ત્રોત - નકારાત્મક) અને ૨. "કાયદાનું સમાન રક્ષણ" (યુએસએ સ્ત્રોત - હકારાત્મક, સમાન સાથે સમાન વ્યવહાર).',
                '[18:50] અનુચ્છેદ ૧૪ ના અપવાદો: અનુચ્છેદ ૩૬૧ (રાષ્ટ્રપતિ અને રાજ્યપાલને ફોજદારી કાર્યવાહીમાંથી મુક્તિ), વિદેશી રાજદૂતો અને સંસદસભ્યો (૧૦૫) / ધારાસભ્યો (૧૯૪).',
                '[22:30] અનુચ્છેદ ૧૫ - ભેદભાવ નિષેધ: માત્ર ૫ આધારો - ધર્મ, મૂળવંશ, જ્ઞાતિ, લિંગ કે જન્મસ્થળ; ૧૫(૩) મહિલા-બાળકો માટે વિશેષ જોગવાઈ; ૧૫(૪) પછાત વર્ગ અનામત (૧મો સુધારો ૧૯૫૧).',
                '[27:10] અનુચ્છેદ ૧૫(૬) અને ૧૬(૬): ૧૦૩મા બંધારણીય સુધારા ૨૦૧૯ દ્વારા આર્થિક નબળા વર્ગ (EWS) માટે શિક્ષણ અને નોકરીમાં ૧૦% અનામત.',
                '[30:20] અનુચ્છેદ ૧૬ - જાહેર રોજગારીમાં તકની સમાનતા: ૭ આધારો પર ભેદભાવ નિષેધ; ૧૬(૪) હેઠળ સામાજિક પછાત વર્ગો માટે અનામત.',
                '[33:15] મંડલ પંચ અને ઇન્દિરા સાહની કેસ (૧૯૯૨): ઓબીસી ૨૭% અનામત માન્ય રખાઈ, પરંતુ સામાન્ય સંજોગોમાં અનામતની કુલ મર્યાદા ૫૦% થી વધવી જોઈએ નહીં; ક્રીમીલેયરનો સિદ્ધાંત.',
                '[36:40] અનુચ્છેદ ૧૭ - અસ્પૃશ્યતા નાબૂદી: નિરપેક્ષ અધિકાર (Absolute Right); નાગરિક અધિકાર સંરક્ષણ અધિનિયમ ૧૯૫૫ અને એટ્રોસિટી એક્ટ ૧૯૮૯.',
                '[40:15] અનુચ્છેદ ૧૮ - ખિતાબોની નાબૂદી: લશ્કરી અને શૈક્ષણિક સિવાય તમામ ખિતાબો પ્રતિબંધિત (રાયબહાદુર, સર વગેરે).',
                '[42:30] બાલાજી રાઘવન કેસ (૧૯૯૬): ભારતરત્ન અને પદ્મ પુરસ્કારો "ખિતાબ" નથી પણ "રાષ્ટ્રીય સન્માન/પુરસ્કાર" છે, તેથી અનુચ્છેદ ૧૮ નું ઉલ્લંઘન નથી; પરંતુ તેનો ઉપયોગ ઉપસર્ગ/પ્રત્યય તરીકે કરી શકાતો નથી.',
