### 🌟 DPSP નો બંધારણીય પરિચય & દર્શન
* **ભાગ:** ૪ | **અનુચ્છેદ:** ૩૬ થી ૫૧ | **સ્ત્રોત:** આયર્લેન્ડનું બંધારણ (૧૯૩૭) - આયર્લેન્ડે સ્પેન પાસેથી લીધું.
* **૧૯૩૫ નો કાયદો:** ભારત સરકાર અધિનિયમ ૧૯૩૫ ના **"ઇન્સ્ટ્રુમેન્ટ ઓફ ઇન્સ્ટ્રક્શન્સ"** સમાન (ડૉ. બાબાસાહેબ આંબેડકર).
* **ઉદ્દેશ્ય:** ભારતમાં "પોલીસ રાજ્ય" ના સ્થાને **"કલ્યાણકારી રાજ્ય" (Welfare State)** સ્થાપવું અને **સામાજિક-આર્થિક લોકશાહી** નું નિર્માણ કરવું.
* **મહત્વના કથનો:**
  * **કે. ટી. શાહ:** "DPSP એવો ચેક છે જેનું ચૂકવણું બેંકની અનુકૂળતા પર છોડાયું છે."
  * **ગ્રેનવિલ ઓસ્ટિન:** "DPSP અને મૂળભૂત અધિકારો બંધારણનો અંતરાત્મા (Conscience) છે."

