### 🌟 મૂળભૂત ફરજો (Fundamental Duties) નો પરિચય & સ્ત્રોત
* **બંધારણીય સ્થાન:** ભાગ - ૪-A (Part IV-A) | **અનુચ્છેદ:** ૫૧-A (Article 51A).
* **મૂળ બંધારણમાં:** **શૂન્ય (૦) ફરજો** (મૂળ બંધારણમાં મૂળભૂત ફરજો સામેલ નહોતી).
* **સ્ત્રોત દેશ:** **પૂર્વ સોવિયેત સંઘ (USSR - રશિયા)**.
* **વિશ્વ પરિપ્રેક્ષ્ય:** મોટાભાગના લોકશાહી દેશો (USA, UK, કેનેડા, ફ્રાન્સ વગેરે) માં ફરજો બંધારણમાં નથી; માત્ર **જાપાન** એકમાત્ર લોકશાહી દેશ હતો જેણે બંધારણમાં ફરજો રાખી હતી.

---

### 🏛️ સરદાર સ્વર્ણસિંહ સમિતિ (૧૯૭૬) & બંધારણીય સુધારાઓ
* **સ્વર્ણસિંહ સમિતિ (૧૯૭૬):** કટોકટી દરમિયાન કોંગ્રેસ સરકાર દ્વારા રચના; બંધારણમાં **૮ મૂળભૂત ફરજો** ઉમેરવાની ભલામણ કરી.
* **અસ્વીકૃત ભલામણો (પરીક્ષાલક્ષી):**
  1. કરવેરા ભરવાની ફરજ (Duty to pay taxes).
  2. ફરજ ન પાળવા બદલ સંસદ દ્વારા દંડ/સજા કરવાની સત્તા.
  3. સજા સામે અદાલતમાં પડકારવા પર પ્રતિબંધ.
* **૪૨મો બંધારણીય સુધારો, ૧૯૭૬:**
  * બંધારણમાં નવો ભાગ ૪-A અને કલમ ૫૧-A ઉમેરીને **૧૦ મૂળભૂત ફરજો** દાખલ કરી.
  * અમલ તારીખ: **૩ જાન્યુઆરી ૧૯૭૭** (તેથી ૩ જાન્યુઆરી = **મૂળભૂત ફરજ દિન**).
* **૮૬મો બંધારણીય સુધારો, ૨૦૦૨:**
  * અટલ બિહારી વાજપેયી સરકાર દ્વારા **૧૧મી ફરજ [૫૧-A(k)]** ઉમેરાઈ: ૬ થી ૧૪ વર્ષના બાળકોને શિક્ષણની તક આપવાની માતા-પિતા કે વાલીની ફરજ.
  * **હાલમાં કુલ ૧૧ મૂળભૂત ફરજો છે.**

---

### 📜 તમામ ૧૧ મૂળભૂત ફરજોની વિગતવાર યાદી (Article 51A (a) to (k))
1. **૫૧-A(a):** બંધારણનું પાલન કરવું, આદર્શો, સંસ્થાઓ, **રાષ્ટ્રધ્વજ અને રાષ્ટ્રગાન** નો આદર કરવો.
2. **૫૧-A(b):** આઝાદી માટેની રાષ્ટ્રીય લડતના **ઉમદા આદર્શોને હૃદયમાં સંઘરવા** અને અનુસરવું.
3. **૫૧-A(c):** ભારતનું **સાર્વભૌમત્વ, એકતા અને અખંડિતતા** નું રક્ષણ કરવું અને તેને જાળવવું.
4. **૫૧-A(d):** દેશનું રક્ષણ કરવું અને રાષ્ટ્રીય સેવા બજાવવાની હાકલ થતાં સેવા આપવી.
5. **૫૧-A(e):** ભ્રાતૃત્વ અને સમરસતા વધારવી તથા **સ્ત્રીઓના ગૌરવને હાનિ પહોંચાડતા વ્યવહારોનો ત્યાગ કરવો**.
6. **૫૧-A(f):** આપણી **સામાસિક (સંયુક્ત) સંસ્કૃતિના સમૃદ્ધ વારસાનું મૂલ્ય સમજી જતન કરવું**.
7. **૫૧-A(g):** વનો, તળાવો, નદીઓ અને વન્યજીવો સહિત **કુદરતી પર્યાવરણનું રક્ષણ-સુધારણા અને જીવદયા (અનુકંપા)** રાખવી.
8. **૫૧-A(h):** **વૈજ્ઞાનિક અભિગમ (માનસ), માનવતાવાદ તથા જિજ્ઞાસા અને સુધારણાની ભાવના** કેળવવી.
9. **૫૧-A(i):** **જાહેર મિલકતનું રક્ષણ કરવું** અને હિંસાનો ત્યાગ કરવો.
10. **૫૧-A(j):** રાષ્ટ્ર સતત નવી ઊંચાઈઓ સર કરે તે માટે તમામ ક્ષેત્રોમાં **ઉત્કૃષ્ટતા (શ્રેષ્ઠતા)** હાંસલ કરવા પ્રયત્ન કરવો.
11. **૫૧-A(k):** ૬ થી ૧૪ વર્ષની વયના બાળકને **શિક્ષણની તકો પૂરી પાડવી** (માતા-પિતા/વાલીની ફરજ - ૮૬મો સુધારો).

