              title: '👑 ભારતના રાષ્ટ્રપતિ (ભાગ-૪: તમામ ૧૫ રાષ્ટ્રપતિઓ, કાર્યકારી રાષ્ટ્રપતિ, વિટોનો ઉપયોગ અને બંધારણીય તુલના)',
